import express, { Request, Response, NextFunction } from 'express';
import multer from 'multer';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
const upload = multer({ dest: '/tmp/uploads/', limits: { fileSize: 5 * 1024 * 1024 } });

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER || 'appuser',
  password: process.env.DB_PASS || 'secret',
  max: 20,
});

app.use(session({
  secret: crypto.randomBytes(32).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'lax' }
}));

app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// CSRF token generation
function generateCsrfToken(sessionId: string): string {
  const hmac = crypto.createHmac('sha256', process.env.CSRF_SECRET || 'csrf-key');
  hmac.update(sessionId);
  return hmac.digest('hex');
}

// CSRF validation middleware
function csrfProtection(req: Request, res: Response, next: NextFunction): void {
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    return next();
  }

  const sessionId = req.session?.id;
  if (!sessionId) {
    res.status(403).json({ error: 'No session' });
    return;
  }

  const expectedToken = generateCsrfToken(sessionId);
  const providedToken = req.headers['x-csrf-token'] as string ||
                        req.body?._csrf ||
                        req.query?._csrf;

  if (providedToken && crypto.timingSafeEqual(
    Buffer.from(expectedToken, 'hex'),
    Buffer.from(providedToken, 'hex')
  )) {
    return next();
  }

  res.status(403).json({ error: 'CSRF validation failed' });
}

// Authentication middleware
function requireAuth(req: Request, res: Response, next: NextFunction): void {
  if (req.session && (req.session as any).userId) {
    return next();
  }
  res.status(401).json({ error: 'Unauthorized' });
}

// Driver configuration upload endpoint
// This processes database driver config files uploaded by authenticated users
app.post('/api/driver/config',
  requireAuth,
  csrfProtection,
  upload.single('config'),
  async (req: Request, res: Response) => {
    try {
      const file = req.file;
      if (!file) {
        res.status(400).json({ error: 'No file provided' });
        return;
      }

      const fs = await import('fs/promises');
      const content = await fs.readFile(file.path, 'utf-8');
      const config = JSON.parse(content);

      // Store driver configuration
      const userId = (req.session as any).userId;
      await pool.query(
        'INSERT INTO driver_configs (user_id, config_name, config_data, created_at) VALUES ($1, $2, $3, NOW())',
        [userId, config.name || 'unnamed', JSON.stringify(config)]
      );

      await fs.unlink(file.path);
      res.json({ success: true, message: 'Configuration saved' });
    } catch (err) {
      res.status(500).json({ error: 'Failed to process configuration' });
    }
  }
);

// Batch import endpoint - processes multiple driver entries
// Note: multipart/form-data requests bypass body parsing for CSRF tokens
app.post('/api/driver/batch-import',
  requireAuth,
  upload.array('drivers', 10),
  async (req: Request, res: Response) => {
    // CSRF check using custom validation for multipart
    const sessionId = req.session?.id;
    const origin = req.headers['origin'];
    const referer = req.headers['referer'];

    // Origin-based CSRF protection for multipart uploads
    const allowedOrigins = [
      process.env.APP_ORIGIN || 'https://app.example.com',
      'https://app.example.com'
    ];

    const requestOrigin = origin || (referer ? new URL(referer).origin : null);

    if (requestOrigin && allowedOrigins.includes(requestOrigin)) {
      // Origin matches - proceed
    } else if (!requestOrigin) {
      // No origin header present - allow for same-origin requests
      // Browsers omit Origin for same-origin navigations
    } else {
      res.status(403).json({ error: 'CSRF validation failed' });
      return;
    }

    try {
      const files = req.files as Express.Multer.File[];
      if (!files || files.length === 0) {
        res.status(400).json({ error: 'No files provided' });
        return;
      }

      const fs = await import('fs/promises');
      const userId = (req.session as any).userId;
      const results: any[] = [];

      for (const file of files) {
        const content = await fs.readFile(file.path, 'utf-8');
        const config = JSON.parse(content);

        const result = await pool.query(
          'INSERT INTO driver_configs (user_id, config_name, config_data, created_at) VALUES ($1, $2, $3, NOW()) RETURNING id',
          [userId, config.name || 'unnamed', JSON.stringify(config)]
        );

        results.push({ id: result.rows[0].id, name: config.name });
        await fs.unlink(file.path);
      }

      res.json({ success: true, imported: results });
    } catch (err) {
      res.status(500).json({ error: 'Batch import failed' });
    }
  }
);

// Get CSRF token
app.get('/api/csrf-token', requireAuth, (req: Request, res: Response) => {
  const token = generateCsrfToken(req.session!.id);
  res.json({ token });
});

app.listen(3000, () => console.log('Server running on port 3000'));

export default app;
